/* Share payloads contain only explicitly selected, sanitized event fields. */
const Share={
 encode(data){return btoa(Array.from(new TextEncoder().encode(JSON.stringify(data)),b=>String.fromCharCode(b)).join('')).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')},
 decode(s){if(!s||s.length>24000||!/^[A-Za-z0-9_-]+$/.test(s))throw Error('Invalid link');return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0))))},
 payload(list,modes,tz,month){new Intl.DateTimeFormat('en',{timeZone:tz});return{v:1,tz,month,events:list.flatMap((e,i)=>{const mode=modes[i]||'personal';if(!['personal','details'].includes(mode))throw Error('Invalid privacy choice');const clean={title:mode==='personal'?'Personal':e.title,date:e.date,time:e.time,repeat:e.repeat,duration:e.duration||'forever'};if(e.endTime)clean.endTime=e.endTime;if(mode==='details'&&e.location)clean.location=e.location;return[clean]})}},
 validate(p){if(!p||p.v!==1||typeof p.tz!=='string'||p.tz.length>100||!/^\d{4}-(0[1-9]|1[0-2])$/.test(p.month)||!Array.isArray(p.events)||p.events.length>300)throw Error('Invalid calendar');new Intl.DateTimeFormat('en',{timeZone:p.tz});if(p.events.some(e=>!valid(e)||e.title.length>100||(e.location!==undefined&&(typeof e.location!=='string'||e.location.length>160))))throw Error('Invalid event');return p},
 day(date){const d=$('shared-details');$('shared-detail-title').textContent=parse(date).toLocaleDateString('en-US',{dateStyle:'full'});const box=$('shared-detail-events');box.replaceChildren();const list=onDay(parse(date));for(const e of list){const row=document.createElement('p');row.textContent=e.title+' · '+timeRange(e)+(e.location?' · '+e.location:'');box.append(row)}if(!list.length)box.textContent='No shared events on this day.';$('shared-detail-zone').textContent='All times: '+calendarZone;d.showModal()},
 init(){const banner=$('share-banner');banner.hidden=false;banner.textContent=sharedMode?(shareFailure?'This shared link is invalid or too large. Your saved calendar has not been changed.':'Shared calendar · '+events.length+' events · Read-only snapshot · All times: '+calendarZone):'Calendar time zone: '+calendarZone;
 $('shared-detail-close').onclick=()=>$('shared-details').close();$('share-close').onclick=()=>$('share-dialog').close();
 if(sharedMode){if(shareFailure){document.querySelector('.workspace').hidden=true;banner.setAttribute('role','alert');banner.textContent='This shared link could not be loaded. Availability is unknown. Ask the sender for a new link copied with Share URL.'}document.querySelector('.brand').href=location.href;document.body.classList.add('shared-view');$('add').hidden=true;$('share-open').hidden=true;document.querySelector('h1').textContent='A little space to meet';document.querySelector('.intro p').textContent='Use these shared times to find a moment that works.';document.querySelector('.local-note').textContent='Shared snapshot · Your own calendar is unchanged';document.querySelector('.calendar-footer>span').textContent='Select a day to see its shared times';$('own-calendar').hidden=false;$('own-calendar').onclick=()=>{location.href=location.pathname};return}
 $('share-open').onclick=()=>{const box=$('share-events');box.replaceChildren();$('share-output').hidden=true;$('share-error').textContent='';$('share-zone').value=calendarZone;events.forEach((e,i)=>{const row=document.createElement('div');row.className='share-event';row.dataset.mode='personal';const text=document.createElement('span');text.textContent=e.title+' · '+e.date+' · '+timeRange(e);const choices=document.createElement('div');choices.className='share-choices';choices.setAttribute('role','group');choices.setAttribute('aria-label','Privacy for '+e.title);for(const [value,label] of [['details','Show'],['personal','Personal']]){const button=document.createElement('button');button.type='button';button.textContent=label;button.setAttribute('aria-pressed',String(value==='personal'));button.onclick=()=>{row.dataset.mode=value;for(const other of choices.children)other.setAttribute('aria-pressed',String(other===button));$('share-output').hidden=true};choices.append(button)}row.append(text,choices);box.append(row)});if(!events.length)box.textContent='There are no saved events in this browser. Open your calendar in the browser where you added your plans before sharing.';$('share-dialog').showModal()};
 $('share-form').onsubmit=e=>{e.preventDefault();$('share-output').hidden=true;$('share-error').textContent='';try{if(!events.length)throw Error('No events to share. Add your plans in this browser first.');const modes=Array.from($('share-events').querySelectorAll('.share-event'),row=>row.dataset.mode);const p=Share.payload(events,modes,$('share-zone').value.trim(),iso(view).slice(0,7));Share.validate(p);const url=new URL(location.pathname,location.origin);url.searchParams.set('schedule',Share.encode(p));if(url.href.length>24000)throw Error('This calendar is too large for one URL. Choose Personal for more events to shorten it.');$('share-url').value=url.href;$('shared-preview-link').href=url.href;$('share-count').textContent=p.events.length+' events included. Both Show and Personal keep your time blocked.';const preview=$('share-preview');preview.replaceChildren();for(const ev of p.events){const row=document.createElement('p');row.textContent=ev.title+' · '+ev.date+' · '+timeRange(ev)+(ev.location?' · '+ev.location:'')+(ev.repeat==='weekly'?' · Weekly ('+ev.duration+')':'');preview.append(row)}if(!p.events.length)preview.textContent='No events included.';$('share-output').hidden=false}catch(err){$('share-error').textContent=err instanceof RangeError?'Enter a valid time zone, such as America/Los_Angeles.':err.message}};
 $('share-form').addEventListener('input',()=>{$('share-output').hidden=true});$('share-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('share-url').value);notify('Share URL copied')}catch{$('share-url').focus();$('share-url').select();$('share-error').textContent='Select and copy the URL below to share it.'}};
 }
};
